import {PropertyBinding} from 'three';
const text=v=>typeof v==='string'&&v.length<=200;
export function validRetargetMorphs(rows){return rows===undefined||Array.isArray(rows)&&rows.length<=256&&new Set(rows.map(r=>r?.targetMesh+'|'+r?.target)).size===rows.length&&rows.every(r=>r&&text(r.source)&&r.source&&text(r.target)&&r.target&&text(r.sourceMesh)&&text(r.targetMesh)&&[r.scale,r.offset,r.min,r.max].every(v=>Number.isFinite(v)&&Math.abs(v)<=100000)&&r.min<=r.max);}
function find(group,name,mesh){const found=[];group?.traverse(node=>{const index=node.morphTargetDictionary?.[name];if(index!==undefined&&(!mesh||node.name===mesh))found.push({node,index});});if(found.length!==1)throw Error(found.length?'같은 이름의 모프가 여러 개예요. 메시를 지정하세요: '+name:'모프가 없어요: '+name);return found[0];}
export class RetargetMorphs{
 constructor(group,rows,slot){this.rows=(rows||[]).map(mapping=>{const target=find(group,mapping.target,mapping.targetMesh),binding=PropertyBinding.create(target.node,'.morphTargetInfluences['+mapping.target+']');binding.displayName=target.node.name+'.morphTargetInfluences['+mapping.target+']';binding.bind();return {mapping,target,slot:slot(target.node.uuid+'|morphTargetInfluences|'+target.index,[target.node.morphTargetInfluences[target.index]],'number',target.node,binding)};});}
 apply(source,pose,input,weight){if(this.source!==source){this.bindings=this.rows.map(row=>find(source,row.mapping.source,row.mapping.sourceMesh));this.source=source;}for(let i=0;i<this.rows.length;i++){const {mapping:m,slot}=this.rows[i],from=this.bindings[i],value=from.node.morphTargetInfluences[from.index];if(!Number.isFinite(value))throw Error('원본 모프 값이 유한하지 않아요.');const corrected=Math.max(m.min,Math.min(m.max,value*m.scale+m.offset));pose[slot][0]=input[slot][0]*(1-weight)+corrected*weight;}}
}
